    [Theory]
    [MemberData(nameof(OriginalRows))]
    public void Source_whole_validator_and_kill_preserve_grid_rng_and_ordered_metadata(
        int type, int style, int profile, bool populated, int member, bool kill, int metadataProfile,
        string gridHash, string metadataHash, string rngHash, int next)
    {
        const int seed = 1458; bool holder = type is 395 or 471 or 698;
        bool verticalJar = profile >= 100; if (verticalJar) profile -= 100;
        int width = type is 471 or 475 ? 3 : type == 698 ? 1 : 2;
        int height = type is 395 or 698 ? 2 : type == 475 ? 4 : 3;
        WorldTileEntityKind kind = type switch
        {
            378 => WorldTileEntityKind.TrainingDummy,
            395 => WorldTileEntityKind.ItemFrame,
            470 => WorldTileEntityKind.DisplayDoll,
            471 => WorldTileEntityKind.WeaponsRack,
            475 => WorldTileEntityKind.HatRack,
            _ => WorldTileEntityKind.DeadCellsDisplayJar
        };
        var tiles = new WorldTileStore(new(80, 80)); var records = new List<WorldTileEntity>();
        if (metadataProfile != 1)
        {
            WorldTileEntityPayload payload;
            if (holder) payload = new WorldItemTileEntityPayload(new((short)(populated ? 353 : 0), 0, (short)(populated ? 3 : 0)));
            else if (type == 378) payload = new WorldTrainingDummyPayload((short)(populated ? 5 : -1));
            else
            {
                WorldTileEntityItem?[] eq = new WorldTileEntityItem?[type == 470 ? 9 : 2], dy = new WorldTileEntityItem?[type == 470 ? 9 : 2];
                if (populated) { eq[0] = new(8, 0, 3); dy[0] = new(61, 0, 2); }
                payload = type == 470 ? new WorldDisplayDollPayload(0, eq, dy, populated ? new WorldTileEntityItem(8, 0, 1) : null) : new WorldHatRackPayload(eq, dy);
            }
            records.Add(new(5, 40, 40, metadataProfile == 2 ? WorldTileEntityKind.FoodPlatter : kind, payload));
        }
        if (holder) foreach (var e in new[] { (id: 9, x: 45, y: 40), (id: 13, x: 45, y: 45) }) records.Add(new(e.id, (short)e.x, (short)e.y,
            WorldTileEntityKind.FoodPlatter, new WorldItemTileEntityPayload(new(353, 0, 3))));
        Assert.True(tiles.TryAttachTileEntities(records.ToArray(), 1000));
        for (int x = 0; x < width; x++) for (int y = 0; y < height; y++)
        {
            var t = new WorldTile
            {
                Type = (ushort)type,
                Flags = WorldTileFlags.Active,
                FrameX = (short)((verticalJar ? 0 : style * width * 18) + x * 18),
                FrameY = (short)((verticalJar ? style * 36 : 0) + y * 18),
                Wall = (ushort)(holder ? (type == 471 ? 7 : 0) : 7),
                TileColor = 5,
                WallColor = 7
            };
            if (profile == 1 && x == width - 1 && y == height - 1) t.Flags = 0;
            if (profile == 2 && x == width - 1 && y == height - 1) t.Type = 1;
            if (profile == 3 && x == width - 1 && y == height - 1) t.FrameX++;
            if (profile == 4 && x == width - 1 && y == height - 1) t.FrameY += 18;
            if (holder && profile == 5) t.Wall = 7;
            if (holder && profile == 6) t.Wall = 0;
            tiles.Set(40 + x, 40 + y, in t);
        }
        if (holder)
        {
            WorldTile anchor = new() { Type = 1, Flags = WorldTileFlags.Active };
            if (profile == 7) Assert.True(anchor.TrySetSourceShape(true, 4));
            if (profile == 8) anchor.Flags |= WorldTileFlags.Inactive;
            if (profile == 9) anchor.Type = 19; if (profile == 10) anchor.Type = 213; if (profile == 11) anchor.Type = 380;
            if (type == 395) { if (profile != 0 && profile != 6) for (int x = 0; x < 2; x++) tiles.Set(40 + x, 42, in anchor); }
            else if (type == 698) { if (profile != 0 && profile != 6) tiles.Set(40, 39, in anchor); }
            else if (profile is 0 or 7 or 8 or 9 or 10 or 11) { var t = tiles.Get(42, 42); t.Wall = 0; tiles.Set(42, 42, in t); }
        }
        else for (int x = 0; x < width; x++)
        {
            var t = new WorldTile { Type = (ushort)(profile == 9 ? 19 : 1), Flags = profile == 0 ? 0 : WorldTileFlags.Active };
            if (profile == 5) Assert.True(t.TrySetSourceShape(true, 4)); if (profile == 6) Assert.True(t.TrySetSourceShape(false, 2));
            if (profile == 7) Assert.True(t.TrySetSourceShape(false, 4)); if (profile == 8) t.Flags |= WorldTileFlags.Inactive;
            tiles.Set(40 + x, 40 + height, in t);
        }
        var random = new FixtureRandom(seed); var frame = new GenerationTileFraming1458(tiles, random);
        if (kill) frame.KillTile(40 + member % width, 40 + member / width); else frame.TileFrame(40 + member % width, 40 + member / width);
        Assert.Equal(gridHash, GridDigest(tiles));
        if (holder)
        {
            var owner = tiles.RuntimeTileEntities!; Assert.True(owner.TryPrepare(1, out var prepared)); Assert.NotNull(prepared);
            Assert.True(prepared.TryStageEmptyPlacement(60, 60, WorldTileEntityKind.DisplayDoll, out int id)); Assert.Equal(14, id); Assert.True(prepared.TrySeal());
            WorldSectionId[] sections = [TerrariaSectionGeometry.FromTile(tiles.Dimensions, 60, 60)];
            tiles.BeginMetadataMutation(sections); try { Assert.True(prepared.TryAdoptUnpublished()); } finally { tiles.EndMetadataMutation(sections); }
        }
        using var m = new MemoryStream(); Assert.Equal(WorldFileTileEntityEncodeResult.Encoded,
            WorldFileTileEntityEncoder.TryEncode(tiles.RuntimeTileEntities!.CaptureSnapshot(), new(80, 80), 1000, m, out _));
        Assert.Equal(metadataHash, Convert.ToHexString(SHA256.HashData(m.ToArray())));
        Assert.Equal(rngHash, RngDigest(random.Source)); Assert.Equal(next, random.Next());
    }
    private static string GridDigest(WorldTileStore tiles)
    {
        using var m = new MemoryStream(); using (var w = new BinaryWriter(m, Encoding.UTF8, true)) for (int x = 0; x < 80; x++) for (int y = 0; y < 80; y++)
        {
            var s = tiles.Get(x, y); w.Write(s.IsActive); w.Write(s.Type); w.Write(s.Wall); w.Write(s.FrameX); w.Write(s.FrameY);
            w.Write(s.LiquidAmount); w.Write((byte)s.LiquidKind); w.Write(s.IsHalfBrick); w.Write(s.SourceSlope); w.Write(s.TileColor); w.Write(s.WallColor);
            w.Write((s.Flags & WorldTileFlags.WireRed) != 0); w.Write((s.Flags & WorldTileFlags.WireBlue) != 0); w.Write((s.Flags & WorldTileFlags.WireGreen) != 0);
            w.Write((s.Flags & WorldTileFlags.WireYellow) != 0); w.Write(s.HasActuator); w.Write(s.IsActuated); w.Write(s.IsBlockInvisible);
            w.Write(s.IsBlockFullbright); w.Write(s.IsWallInvisible); w.Write(s.IsWallFullbright);
        }
        return Convert.ToHexString(SHA256.HashData(m.ToArray()));
    }
    private static string RngDigest(TerraRuntime.Core.VanillaUnifiedRandom1458 random)
    {
        const BindingFlags flags = BindingFlags.Instance | BindingFlags.NonPublic; using var m = new MemoryStream();
        using (var w = new BinaryWriter(m, Encoding.UTF8, true))
        {
            w.Write((uint)typeof(TerraRuntime.Core.VanillaUnifiedRandom1458).GetField("inext", flags)!.GetValue(random)!);
            foreach (int v in (int[])typeof(TerraRuntime.Core.VanillaUnifiedRandom1458).GetField("seedArray", flags)!.GetValue(random)!) w.Write(v);
        }
        return Convert.ToHexString(SHA256.HashData(m.ToArray()));
    }
    private sealed class FixtureRandom(int seed) : IWorldGenerationVanillaRandom
    {
        internal readonly TerraRuntime.Core.VanillaUnifiedRandom1458 Source = new(seed);
        public int Next() => Source.Next(); public int Next(int max) => Source.Next(max); public int Next(int min, int max) => Source.Next(min, max);
        public double NextDouble() => Source.NextDouble(); public void NextBytes(byte[] bytes) => Source.NextBytes(bytes);
    }
